import { promises as fs } from "fs";
import path from "path";
import { execFile } from "child_process";
import { promisify } from "util";

const exec = promisify(execFile);

export const FIXTURE_NOTICE =
  "SYNTHETIC DEMO FIXTURE — generated by CarryForward's fixture script. Not a real project; all content is invented for demonstration and testing.";

async function git(target: string, ...args: string[]): Promise<void> {
  await exec("git", ["-C", target, ...args]);
}

async function write(target: string, rel: string, content: string): Promise<void> {
  const file = path.join(target, rel);
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, content, "utf8");
}

export async function generateFixture(target: string): Promise<{ root: string; note: string }> {
  await fs.rm(target, { recursive: true, force: true });
  await fs.mkdir(target, { recursive: true });

  await write(target, "FIXTURE-README.md", `# ${FIXTURE_NOTICE}\n\nThis repository exists so CarryForward's demo and tests have a deterministic target.\nReset it any time with \`npm run fixture\`.\n`);

  await write(
    target,
    "AGENTS.md",
    [
      "# Agent instructions (fixture)",
      "",
      FIXTURE_NOTICE,
      "",
      "## Principles",
      "",
      "- Never commit secrets or credential values.",
      "- Always write tests for new endpoints.",
      "",
    ].join("\n") + "\n"
  );

  await write(
    target,
    "PROJECT-CORE.md",
    [
      "# Project core (fixture)",
      "",
      `> ${FIXTURE_NOTICE}`,
      "",
      "## Principles",
      "",
      "- All database access must go through the repository layer in src.",
      "",
      "## Constraints",
      "",
      "- TODO: pick a real license before this fixture pretends to ship.",
      "",
    ].join("\n") + "\n"
  );

  await write(
    target,
    "PROJECT_STATUS.md",
    [
      "# Status (fixture)",
      "",
      "- Repository-layer persistence — WORKING",
      "- Cloud sync: ROADMAP",
      "",
    ].join("\n") + "\n"
  );

  await write(
    target,
    "docs/ARCHITECTURE.md",
    [
      "# Architecture (fixture)",
      "",
      "Data access goes through the repository layer in src; services depend on repositories.",
      "",
    ].join("\n") + "\n"
  );

  await write(
    target,
    "doc-of-journey/decisions/0001-repository-layer.md",
    [
      "# Use a repository layer for all data access",
      "",
      "Date: 2026-10-26",
      "Status: accepted",
      "",
      "## Decision",
      "",
      "All database access must go through the repository layer in src. Services call repositories; repositories own queries.",
      "",
      "## Consequences",
      "",
      "Direct queries in services are a violation of this decision.",
      "",
    ].join("\n") + "\n"
  );

  await write(
    target,
    "doc-of-journey/decisions/0002-query-through-gateway.md",
    [
      "# Route queries through the data gateway",
      "",
      "Date: 2026-10-27",
      "Status: accepted",
      "",
      "## Decision",
      "",
      "New services call the data gateway instead of repositories directly. Supersedes 0001, whose status text was never updated — this is the fixture's controlled conflict case.",
      "",
      "## Consequences",
      "",
      "ADR 0001 remains marked accepted in its source file, so Maintenance shows a conflict candidate with both sides.",
      "",
    ].join("\n") + "\n"
  );

  await write(
    target,
    "package.json",
    [
      "{",
      '  "name": "demo-repo",',
      '  "private": true,',
      '  "scripts": {',
      '    "test": "vitest run",',
      '    "lint": "eslint ."',
      "  },",
      '  "dependencies": {',
      '    "express": "^4.21.2"',
      "  }",
      "}",
      "",
    ].join("\n")
  );

  await write(target, "vitest.config.ts", "export default {};\n");

  await write(target, "src/repositories/user-repo.ts", "export const userRepo = { list: () => [] };\n");

  await write(
    target,
    "src/services/user-service.ts",
    [
      "import { userRepo } from '../repositories/user-repo';",
      "",
      "export const getUsers = () => userRepo.list();",
      "",
    ].join("\n")
  );

  await write(target, "src/services/user-service.test.ts", "it('lists users via the repository', () => {});\n");

  await git(target, "init");
  await git(target, "config", "user.email", "fixture@demo.invalid");
  await git(target, "config", "user.name", "Fixture Generator");
  await git(target, "add", "-A");
  await git(target, "commit", "-m", "fixture: initial state");
  await git(target, "commit", "--allow-empty", "-m", "fixture: pending change marker");

  await fs.appendFile(
    path.join(target, "src/services/user-service.ts"),
    [
      "",
      "export const badQuery = () => {",
      "  const rows = db.query('SELECT * FROM users');",
      "  return rows;",
      "};",
      "",
    ].join("\n"),
    "utf8"
  );

  return {
    root: target,
    note: `Fixture created at ${target}. The pending violating change is left unstaged so 'git diff' shows it.`,
  };
}

const isMain = typeof require !== "undefined" && require.main === module;
if (isMain) {
  const target = process.argv[2] ?? path.join(process.cwd(), "fixtures", "demo-repo");
  generateFixture(path.resolve(target))
    .then((r) => console.log(r.note))
    .catch((err) => {
      console.error(`Fixture generation failed: ${(err as Error).message}`);
      process.exit(1);
    });
}
